from __future__ import annotations

import polars as pl
import pytest
from ds.cli.data import CHAR_PARQUET_PATH, DATA_DIR
from ds.data import CHAR_GROUP_NAMES, CHAR_GROUPS, CharEnum, CharGroup, CharId
from ds.data.raw.roster import CHARS_MODULE, char_enum_source, write_char_enums
from pydantic import BaseModel, ValidationError

CHARS = pl.read_parquet(CHAR_PARQUET_PATH)


def test_generated_enums_match_char_parquet():
    """The enums are generated code. If this fails, run `uv run ds data char_enum`"""
    assert char_enum_source(CHARS) in CHARS_MODULE.read_text(), "run `uv run ds data char_enum`"
    assert [member.value for member in CharId] == CHARS["id"].to_list()
    assert [member.value for member in CharGroup] == CHARS["char_group"].unique(maintain_order=True).to_list()
    assert (len(CharId), len(CharGroup)) == (89, 86)


def test_regenerating_changes_nothing_and_a_new_fighter_would(tmp_path, monkeypatch):
    copy = tmp_path / "chars.py"
    copy.write_text(CHARS_MODULE.read_text())
    monkeypatch.setattr("ds.data.raw.roster.CHARS_MODULE", copy)
    assert write_char_enums(CHARS) is False
    grown = pl.concat([CHARS, CHARS.head(1).with_columns(id=pl.lit("new_fighter"), char_group=pl.lit("new_fighter"))])
    assert write_char_enums(grown) is True
    assert copy.read_text().count('NEW_FIGHTER = "new_fighter"') == 2  # once per enum
    assert copy.read_text().startswith(CHARS_MODULE.read_text().split("# --- generated")[0])  # the rest is untouched


def test_member_names_follow_the_ids():
    assert CharId.LITTLE_MAC == "little_mac"
    assert CharGroup.POKEMON_TRAINER.value == "pokemon_trainer"
    assert all(member.name == member.value.upper() for member in [*CharId, *CharGroup])
    assert issubclass(CharId, CharEnum)
    assert issubclass(CharGroup, CharEnum)


def test_groups_are_picks_not_fighters():
    assert set(CHAR_GROUPS) == set(CHAR_GROUP_NAMES)
    assert not {member.value for member in CharId} & set(CHAR_GROUPS)
    assert set(CHAR_GROUPS) <= {member.value for member in CharGroup}
    grouped = {fighter for members in CHAR_GROUPS.values() for fighter in members}
    assert not grouped & {member.value for member in CharGroup}  # pt_squirtle is not a pick


@pytest.mark.parametrize(
    ("written", "pick"),
    [
        ("little_mac", CharGroup.LITTLE_MAC),
        ("Little Mac", CharGroup.LITTLE_MAC),
        ("mac", CharGroup.LITTLE_MAC),  # part of a name that fits one member
        ("Mr. Game & Watch", CharGroup.MR_GAME_AND_WATCH),
        ("Banjo-Kazooie", CharGroup.BANJO_AND_KAZOOIE),
        ("link", CharGroup.LINK),  # exact, although Young Link and Toon Link contain it
        ("samus", CharGroup.SAMUS),
        ("Pokemon Trainer", CharGroup.POKEMON_TRAINER),
        ("pt_ivysaur", CharGroup.POKEMON_TRAINER),
        ("Charizard", CharGroup.POKEMON_TRAINER),
        ("Pyra/Mythra", CharGroup.PYRA_MYTHRA),
        ("mythra", CharGroup.PYRA_MYTHRA),
    ],
)
def test_picks_parse_what_people_write(written, pick):
    assert CharGroup(written) is pick


def test_fighters_parse_to_one_fighter():
    assert CharId("Squirtle") is CharId.PT_SQUIRTLE
    assert CharId("mythra") is CharId.MYTHRA
    assert CharId("mac") is CharId.LITTLE_MAC
    with pytest.raises(ValueError, match="not a valid CharId"):
        CharId("Pokemon Trainer")  # a pick, not one fighter


@pytest.mark.parametrize("written", ["Goku", "", "bro", "Random Character"])  # 'bro' fits several
def test_unknown_or_ambiguous_is_a_value_error(written):
    with pytest.raises(ValueError, match="not a valid CharGroup"):
        CharGroup(written)


def test_labels_and_icons():
    assert (CharGroup.LITTLE_MAC.label, CharGroup.LITTLE_MAC.icon) == ("Little Mac", "char_icons/little_mac.png")
    assert (CharGroup.POKEMON_TRAINER.label, CharGroup.POKEMON_TRAINER.icon) == (
        "Pokemon Trainer",
        "char_icons/pokemon_trainer.png",
    )
    assert CharGroup.PYRA_MYTHRA.label == "Pyra & Mythra"
    assert (CharId.PT_IVYSAUR.label, CharId.PT_IVYSAUR.icon) == ("Ivysaur", "char_icons/pokemon_trainer.png")
    for member in [*CharId, *CharGroup]:
        assert (DATA_DIR / member.icon).is_file(), member


def test_choices_are_sorted_by_name_for_a_picker():
    choices = CharGroup.choices()
    assert len(choices) == len(CharGroup)
    labels = [choice.label for choice in choices]
    assert labels == sorted(labels, key=str.lower)
    assert choices[0].model_dump() == {
        "value": "banjo_and_kazooie",
        "label": "Banjo & Kazooie",
        "icon": "char_icons/banjo_and_kazooie.png",
    }


def test_as_a_pydantic_field():
    class Query(BaseModel):
        vs: CharGroup | None = None

    assert Query(vs="Little Mac").vs is CharGroup.LITTLE_MAC
    assert Query().vs is None
    assert Query(vs="steve").model_dump_json() == '{"vs":"steve"}'
    with pytest.raises(ValidationError):
        Query(vs="Goku")
    assert Query.model_json_schema()["$defs"]["CharGroup"]["enum"][:2] == ["banjo_and_kazooie", "bayonetta"]
